// GENERATED by scripts/gen_stack_assets.py from infra/events-webhooks.yaml.
// Do not edit by hand: run `python scripts/gen_stack_assets.py`.
export const TEMPLATE_BODY = `AWSTemplateFormatVersion: "2010-09-09"
Description: >-
  Rayito M15 (optional, m15-events-webhooks): lifecycle events (created,
  paused, resumed, killed) emitted on stdout by \`rayd\`, forwarded from a
  CloudWatch Logs subscription, stored for 7 days and delivered to
  registered webhooks with E2B-compatible signatures. Creates one Secrets
  Manager secret (the stack-wide HMAC key), one on-demand DynamoDB table,
  three Lambda functions, one CloudWatch Logs subscription filter, two SQS
  queues (the forwarder's and the deliverer's on-failure destinations) and
  one EventBridge Scheduler rule. Deploy it only if you pass \`events=\` to
  \`Sandbox.create\`; delete the stack to remove everything it created
  (the Secrets Manager secret is force-deleted, losing every already
  registered webhook's ability to re-verify old events). Action names and
  parameters: AWS_API_NOTES.md section 25.

Parameters:
  LogGroupName:
    Type: String
    MinLength: 1
    Description: >-
      The image's CloudWatch Logs log group (the one \`logging="cloudwatch"\`
      already writes rayd's stdout to). The subscription filter reads from
      this group; it is never created by this stack.
  ArtifactBucket:
    Type: String
    MinLength: 3
    Description: >-
      S3 bucket \`OptionalStacks.deploy(artifact_bucket=...)\` already
      uploaded the three Lambdas' code to (same value, so the template can
      reference it alongside the key \`StackArtifact\` resolves).
  ArtifactS3Key:
    Type: String
    MinLength: 1
    Description: >-
      rayito/stacks/<component>/<sha256>.zip, the Lambda zip's key inside the
      rayito/ namespace the IAM templates protect (filled by
      \`OptionalStacks.deploy\`, never set by hand).
  ReconcilerIntervalMinutes:
    Type: Number
    # Default: the SDKs' DEFAULT_RECONCILER_INTERVAL_MINUTES (pinned equal by
    # scripts/tests/test_events_webhooks_template.py). MinValue 2: Scheduler
    # needs the singular \`rate(1 minute)\` for 1, and ScheduleExpression
    # below always renders \`rate(N minutes)\`.
    Default: 5
    MinValue: 2
    MaxValue: 60
    Description: >-
      EventBridge Scheduler rate for the reconciler (§7.4: synthesizes
      \`killed\` events for sandboxes \`ListMicrovms\` no longer reports).

Resources:
  # --- Secret -----------------------------------------------------------
  StackKeySecret:
    Type: AWS::SecretsManager::Secret
    Properties:
      Description: >-
        Rayito events-webhooks stack key: HMAC-SHA256(this, "rayito.events.v1|"
        + sandbox_id) derives each sandbox's own k_sbx (SDK-side,
        \`_lifecycle_events/_keys.py\`). Never pushed into a guest; the
        forwarder Lambda reads it to re-derive k_sbx and verify event MACs.
      GenerateSecretString:
        PasswordLength: 32
        ExcludePunctuation: true
        ExcludeUppercase: false
        ExcludeLowercase: false
        ExcludeNumbers: false
        RequireEachIncludedType: false

  # --- Table --------------------------------------------------------------
  EventsTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Delete
    UpdateReplacePolicy: Delete
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: pk
          AttributeType: S
        - AttributeName: sk
          AttributeType: S
        - AttributeName: gsi1pk
          AttributeType: S
        - AttributeName: gsi1sk
          AttributeType: S
      KeySchema:
        - AttributeName: pk
          KeyType: HASH
        - AttributeName: sk
          KeyType: RANGE
      GlobalSecondaryIndexes:
        - IndexName: gsi1
          KeySchema:
            - AttributeName: gsi1pk
              KeyType: HASH
            - AttributeName: gsi1sk
              KeyType: RANGE
          Projection:
            ProjectionType: ALL
      TimeToLiveSpecification:
        AttributeName: expires_at
        Enabled: true
      StreamSpecification:
        StreamViewType: NEW_IMAGE

  # --- Lambda execution roles (least privilege, one per function) --------
  ForwarderRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal: { Service: lambda.amazonaws.com }
            Action: sts:AssumeRole
      Policies:
        - PolicyName: forwarder
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              # dynamodb:LeadingKeys is the partition key value of each
              # write: the forwarder only ever writes EVENT# and STATE# rows.
              - Sid: WriteEvents
                Effect: Allow
                Action: dynamodb:PutItem
                Resource: !GetAtt EventsTable.Arn
                Condition:
                  ForAllValues:StringLike:
                    dynamodb:LeadingKeys: ["EVENT#*", "STATE#*"]
              - Sid: SendToFailuresQueue
                Effect: Allow
                Action: sqs:SendMessage
                Resource: !GetAtt ForwarderFailuresQueue.Arn
              - Sid: ReadStackKey
                Effect: Allow
                Action: secretsmanager:GetSecretValue
                Resource: !Ref StackKeySecret
              # Only Lambda's own log groups, never the sandboxes' (/rayito/*):
              # a bug in a function can never write lines into an image's log
              # group, which is what the forwarder reads events from.
              - Sid: WriteLogs
                Effect: Allow
                Action: [logs:CreateLogGroup, logs:CreateLogStream, logs:PutLogEvents]
                Resource: !Sub "arn:\${AWS::Partition}:logs:\${AWS::Region}:\${AWS::AccountId}:log-group:/aws/lambda/*"

  DelivererRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal: { Service: lambda.amazonaws.com }
            Action: sts:AssumeRole
      Policies:
        - PolicyName: deliverer
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Sid: ReadStream
                Effect: Allow
                Action:
                  - dynamodb:GetRecords
                  - dynamodb:GetShardIterator
                  - dynamodb:DescribeStream
                  - dynamodb:ListStreams
                Resource: !GetAtt EventsTable.StreamArn
              - Sid: ReadWebhooks
                Effect: Allow
                Action: dynamodb:Query
                Resource: !GetAtt EventsTable.Arn
                Condition:
                  ForAllValues:StringEquals:
                    dynamodb:LeadingKeys: ["WEBHOOK"]
              - Sid: WriteDeliveryDedupe
                Effect: Allow
                Action: dynamodb:PutItem
                Resource: !GetAtt EventsTable.Arn
                Condition:
                  ForAllValues:StringLike:
                    dynamodb:LeadingKeys: ["DELIVERY#*"]
              - Sid: ReadWebhookSecrets
                Effect: Allow
                Action: secretsmanager:GetSecretValue
                Resource: !Sub "arn:\${AWS::Partition}:secretsmanager:\${AWS::Region}:\${AWS::AccountId}:secret:rayito/webhooks/*"
              # Only Lambda's own log groups, never the sandboxes' (/rayito/*):
              # a bug in a function can never write lines into an image's log
              # group, which is what the forwarder reads events from.
              - Sid: WriteLogs
                Effect: Allow
                Action: [logs:CreateLogGroup, logs:CreateLogStream, logs:PutLogEvents]
                Resource: !Sub "arn:\${AWS::Partition}:logs:\${AWS::Region}:\${AWS::AccountId}:log-group:/aws/lambda/*"
              - Sid: SendToFailuresQueue
                Effect: Allow
                Action: sqs:SendMessage
                Resource: !GetAtt DelivererFailuresQueue.Arn

  ReconcilerRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal: { Service: lambda.amazonaws.com }
            Action: sts:AssumeRole
      Policies:
        - PolicyName: reconciler
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              # Scan cannot be narrowed by key (it reads the whole table);
              # the writes are, to the rows a synthesized event touches.
              - Sid: ScanOpenSandboxes
                Effect: Allow
                Action: dynamodb:Scan
                Resource: !GetAtt EventsTable.Arn
              - Sid: WriteSynthesizedEvents
                Effect: Allow
                Action: dynamodb:PutItem
                Resource: !GetAtt EventsTable.Arn
                Condition:
                  ForAllValues:StringLike:
                    dynamodb:LeadingKeys: ["EVENT#*", "STATE#*"]
              - Sid: ListMicrovms
                Effect: Allow
                Action: lambda:ListMicrovms
                Resource: "*"
              # Only Lambda's own log groups, never the sandboxes' (/rayito/*):
              # a bug in a function can never write lines into an image's log
              # group, which is what the forwarder reads events from.
              - Sid: WriteLogs
                Effect: Allow
                Action: [logs:CreateLogGroup, logs:CreateLogStream, logs:PutLogEvents]
                Resource: !Sub "arn:\${AWS::Partition}:logs:\${AWS::Region}:\${AWS::AccountId}:log-group:/aws/lambda/*"

  # --- Lambda functions ---------------------------------------------------
  ForwarderFunction:
    Type: AWS::Lambda::Function
    Properties:
      Runtime: python3.12
      Handler: handlers.forwarder.handler
      Role: !GetAtt ForwarderRole.Arn
      Timeout: 30
      MemorySize: 256
      Code:
        S3Bucket: !Ref ArtifactBucket
        S3Key: !Ref ArtifactS3Key
      Environment:
        Variables:
          EVENTS_TABLE_NAME: !Ref EventsTable
          STACK_KEY_SECRET_ID: !Ref StackKeySecret

  # CloudWatch Logs invokes the forwarder asynchronously: an invocation that
  # still fails after Lambda's own retries (a table write that kept failing;
  # a bad line never fails it, \`handlers/forwarder.py\`) lands here with its
  # batch instead of being discarded. Same shape and cost as
  # DelivererFailuresQueue below: no consumer shipped, within the free tier.
  ForwarderFailuresQueue:
    Type: AWS::SQS::Queue
    Properties:
      MessageRetentionPeriod: 1209600 # 14 days, SQS's own maximum

  ForwarderEventInvokeConfig:
    Type: AWS::Lambda::EventInvokeConfig
    Properties:
      FunctionName: !Ref ForwarderFunction
      Qualifier: $LATEST
      MaximumRetryAttempts: 2
      DestinationConfig:
        OnFailure:
          Destination: !GetAtt ForwarderFailuresQueue.Arn

  ForwarderLogPermission:
    Type: AWS::Lambda::Permission
    Properties:
      FunctionName: !Ref ForwarderFunction
      Action: lambda:InvokeFunction
      Principal: !Sub "logs.\${AWS::Region}.amazonaws.com"
      SourceArn: !Sub "arn:\${AWS::Partition}:logs:\${AWS::Region}:\${AWS::AccountId}:log-group:\${LogGroupName}:*"

  ForwarderSubscription:
    Type: AWS::Logs::SubscriptionFilter
    DependsOn: ForwarderLogPermission
    Properties:
      LogGroupName: !Ref LogGroupName
      DestinationArn: !GetAtt ForwarderFunction.Arn
      FilterPattern: '"rayito.event.v1 "'

  DelivererFunction:
    Type: AWS::Lambda::Function
    Properties:
      Runtime: python3.12
      Handler: handlers.deliverer.handler
      Role: !GetAtt DelivererRole.Arn
      Timeout: 60
      MemorySize: 256
      Code:
        S3Bucket: !Ref ArtifactBucket
        S3Key: !Ref ArtifactS3Key
      Environment:
        Variables:
          EVENTS_TABLE_NAME: !Ref EventsTable

  # A record the deliverer reported as not finished (it ran out of time
  # budget, \`handlers/deliverer.py\`) or that kept failing the whole
  # invocation lands here once \`MaximumRetryAttempts\` is exhausted, instead
  # of disappearing. A webhook that simply answered non-2xx after its
  # attempts is logged by the deliverer, never sent here. Standard queue, no
  # consumer shipped (read it with \`aws sqs receive-message\` or alarm on
  # \`ApproximateNumberOfMessagesVisible\`); within the free tier at this
  # stack's volume.
  DelivererFailuresQueue:
    Type: AWS::SQS::Queue
    Properties:
      MessageRetentionPeriod: 1209600 # 14 days, SQS's own maximum

  DelivererEventSourceMapping:
    Type: AWS::Lambda::EventSourceMapping
    Properties:
      EventSourceArn: !GetAtt EventsTable.StreamArn
      FunctionName: !Ref DelivererFunction
      StartingPosition: LATEST
      BatchSize: 10
      MaximumRetryAttempts: 2
      # A batch that keeps failing is bisected until the one poison record
      # is isolated, rather than retried whole twice and dropped — the
      # other records in the batch still get through.
      BisectBatchOnFunctionError: true
      # The handler returns \`batchItemFailures\` (the first record it could
      # not finish inside its time budget): the retry resumes there, and
      # every webhook already marked \`delivered\` is skipped.
      FunctionResponseTypes: [ReportBatchItemFailures]
      DestinationConfig:
        OnFailure:
          Destination: !GetAtt DelivererFailuresQueue.Arn

  ReconcilerFunction:
    Type: AWS::Lambda::Function
    Properties:
      Runtime: python3.12
      Handler: handlers.reconciler.handler
      Role: !GetAtt ReconcilerRole.Arn
      Timeout: 60
      MemorySize: 256
      Code:
        S3Bucket: !Ref ArtifactBucket
        S3Key: !Ref ArtifactS3Key
      Environment:
        Variables:
          EVENTS_TABLE_NAME: !Ref EventsTable
          # The same value the \`ReconcilerSchedule\` rule below runs on, so
          # the dedupe window (\`domain/dedupe.py\`) can never drift from the
          # actual schedule.
          RECONCILER_INTERVAL_MINUTES: !Ref ReconcilerIntervalMinutes
          # Decision 8: the Lambda runtime's boto3 does not know
          # \`lambda-microvms\`; its model ships in the zip under \`models/\`
          # (\`scripts/gen_stack_assets.py\`), and botocore reads this before
          # any client exists.
          AWS_DATA_PATH: /var/task/models

  ReconcilerSchedulerRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal: { Service: scheduler.amazonaws.com }
            Action: sts:AssumeRole
            Condition:
              StringEquals:
                aws:SourceAccount: !Ref AWS::AccountId
      Policies:
        - PolicyName: invoke-reconciler
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action: lambda:InvokeFunction
                Resource: !GetAtt ReconcilerFunction.Arn

  ReconcilerSchedule:
    Type: AWS::Scheduler::Schedule
    Properties:
      ScheduleExpression: !Sub "rate(\${ReconcilerIntervalMinutes} minutes)"
      FlexibleTimeWindow: { Mode: "OFF" }
      Target:
        Arn: !GetAtt ReconcilerFunction.Arn
        RoleArn: !GetAtt ReconcilerSchedulerRole.Arn

  # --- Operator policy: everything LifecycleEvents() itself calls, direct
  # on this stack's own table/secret/status; the three Lambdas have their
  # own, separate least-privilege roles above. ---------------------------
  EventsOperatorPolicy:
    Type: AWS::IAM::ManagedPolicy
    Properties:
      Description: >-
        Attach to the identity calling LifecycleEvents(...)/events=:
        register_webhook/list_webhooks/delete_webhook/get_events read and
        write the events table directly (no Lambda in that path), status()
        resolves this stack's outputs, and deriving k_sbx reads the stack
        key. SecretStore itself is a separate concern: register_webhook's
        own secret lives under rayito/webhooks/, covered by
        secrets-access.yaml, not this policy.
      PolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Sid: ReadStackKey
            Effect: Allow
            Action: secretsmanager:GetSecretValue
            Resource: !Ref StackKeySecret
          # The SDK only ever writes and deletes WEBHOOK rows: it can never
          # mark a delivery done or plant an event row.
          - Sid: WriteWebhooks
            Effect: Allow
            Action: [dynamodb:PutItem, dynamodb:DeleteItem]
            Resource: !GetAtt EventsTable.Arn
            Condition:
              ForAllValues:StringEquals:
                dynamodb:LeadingKeys: ["WEBHOOK"]
          - Sid: ReadWebhooksAndEvents
            Effect: Allow
            Action: dynamodb:Query
            Resource:
              - !GetAtt EventsTable.Arn
              - !Sub "\${EventsTable.Arn}/index/gsi1"
          - Sid: ResolveStackOutputs
            Effect: Allow
            Action: cloudformation:DescribeStacks
            Resource: !Ref "AWS::StackId"

Outputs:
  EventsTableName:
    Value: !Ref EventsTable
  StackKeySecretArn:
    Description: Pass to LifecycleEvents(stack_key_secret_arn=...) / read by the forwarder.
    Value: !Ref StackKeySecret
  OperatorPolicyArn:
    Description: Attach to the identity that calls events=/register_webhook/get_events.
    Value: !Ref EventsOperatorPolicy
  ReconcilerFunctionArn:
    Value: !GetAtt ReconcilerFunction.Arn
  DelivererFailuresQueueUrl:
    Description: Whole-batch delivery failures (OnFailure destination); empty under normal operation.
    Value: !Ref DelivererFailuresQueue
  ForwarderFailuresQueueUrl:
    Description: Forwarder invocations that failed after Lambda's retries (OnFailure destination); empty under normal operation.
    Value: !Ref ForwarderFailuresQueue
`;
// Base64 of the component's Lambda source zip, or undefined when it has none.
export const ARTIFACT_BASE64: string | undefined =
  "";
